// Command shop is models' example: an app whose models sqlc generates, with
// labels for its enum values, tables and columns generated by models and
// declared by i18n. It prints the labels in the source language.
package main

//go:generate go tool genx

import (
	"context"
	"fmt"

	"github.com/epistemer/models/examples/shop/models"
)

func main() {
	ctx := context.Background() // no translator: the code's English text
	fmt.Println(models.L10nOrder.T(ctx))
	for _, s := range models.AllOrderStatusValues() {
		fmt.Printf("  %s: %s\n", models.L10nOrder_Status.T(ctx), s.Label().T(ctx))
	}
	fmt.Println(models.L10n("table.shop_customer.email").T(ctx))
}
